import {fresh,validate,calculate,snapshot,readBackup,money,percent,formatRatio,normalize,uid} from './model.mjs';
const $=id=>document.getElementById(id),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),clone=s=>JSON.parse(JSON.stringify(s));
const KEY='planer.scenarios.v1',DRAFT='planer.draft.v1',INFO='planer.local-info.v1';
const colors=['#34776b','#7b9b67','#ba995d','#729aa1','#927fa6','#b77e66','#7ca990','#b1ac65','#7e8994'];
let scenarios=[],draft=fresh(),baseline=JSON.stringify(draft),selected=new Set(),baseId='',tab='calculator',timer,toastTimer,corrupt=false,storageBlocked=false,externalPending=false;
let rawScenarios=null,rawDraft=null;
function notify(s){$('toast').textContent=s;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').textContent='',6000)}
function modal(title,text,options){return new Promise(resolve=>{const d=$('dialog');$('dialogTitle').textContent=title;$('dialogText').textContent=text;$('dialogButtons').replaceChildren();options.forEach(([label,value,primary])=>{let b=document.createElement('button');b.textContent=label;b.value=value;b.className='button'+(primary?' primary':'');$('dialogButtons').append(b)});const done=()=>{d.removeEventListener('close',done);resolve(d.returnValue||'cancel')};d.addEventListener('close',done);d.returnValue='cancel';d.showModal()})}
function localError(text){storageBlocked=true;$('persistent').className='notice';$('persistent').textContent=text+' Dane pozostają w pamięci. Możesz wyeksportować poprawny szkic lub scenariusze.';$('draftStatus').textContent='Zapis lokalny niedostępny'}
function download(data,filename){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function backup(list){download({schemaVersion:1,scenarios:list},'planer-scenariusze.json')}
function loadInitial(){try{rawScenarios=localStorage.getItem(KEY);rawDraft=localStorage.getItem(DRAFT);if(rawScenarios)scenarios=readBackup(rawScenarios,false).map((s,i)=>({...s,updatedAt:JSON.parse(rawScenarios).scenarios[i].updatedAt}));if(rawDraft){let saved=JSON.parse(rawDraft);if(saved.schemaVersion!==1||!saved.draft||typeof saved.draft.name!=='string'||typeof saved.draft.annualBudget!=='string'||!['PLN','EUR','USD'].includes(saved.draft.currency)||!Array.isArray(saved.draft.categories)||saved.draft.categories.length>30||saved.draft.categories.some(c=>!c||['id','name','allocationPercent','expectedRoiPercent'].some(k=>typeof c[k]!=='string'))||typeof saved.baseline!=='string')throw Error('Uszkodzony szkic');draft=saved.draft;baseline=saved.baseline}}catch(e){corrupt=true;scenarios=[];draft=fresh();baseline=JSON.stringify(draft);$('persistent').className='notice';$('persistent').innerHTML='<strong>Nie udało się odczytać zapisanych danych.</strong><p>Nie zmieniliśmy oryginalnego zapisu. Pobierz surową kopię przed resetem.</p><div class="actions"><button class="button" id="rawBackup">Pobierz surową kopię</button><button class="button" id="reset">Resetuj dane lokalne</button></div>';$('rawBackup').onclick=()=>download({scenarios:rawScenarios,draft:rawDraft},'planer-surowa-kopia.json');$('reset').onclick=async()=>{if(await modal('Reset danych lokalnych','Usunie to zapisane scenariusze i szkic z tej przeglądarki. Najpierw pobierz surową kopię.',[['Anuluj','cancel'],['Resetuj','yes',true]])==='yes')try{localStorage.removeItem(KEY);localStorage.removeItem(DRAFT);location.reload()}catch{localError('Nie udało się zresetować danych.')}}}}
loadInitial();
function persistDraft(){clearTimeout(timer);timer=setTimeout(()=>{if(corrupt||externalPending)return;try{localStorage.setItem(DRAFT,JSON.stringify({schemaVersion:1,draft,baseline}));$('draftStatus').textContent='Szkic zapisany lokalnie';}catch{localError('Nie udało się zapisać szkicu.')}},300)}
function dirty(){return JSON.stringify(draft)!==baseline}
async function guard(action){if(dirty()){let valid=Object.keys(validate(draft,true).errors).length===0;let options=[['Anuluj','cancel'],['Odrzuć zmiany','discard']];if(valid)options.push(['Zapisz i kontynuuj','save',true]);const choice=await modal('Masz niezapisane zmiany','Szkic jest odtwarzany lokalnie, ale nie jest zapisanym scenariuszem. Co zrobić przed zastąpieniem go?',options);if(choice==='cancel')return;if(choice==='save'&&!await saveScenario(false))return;}action()}
function setDraft(s){draft=clone(s);baseline=JSON.stringify(draft);persistDraft();renderForm();renderResults();showTab('calculator')}
function fieldError(id,text){const el=$(id),err=$('error-'+id);if(el)el.setAttribute('aria-invalid',text?'true':'false');if(err)err.textContent=text||''}
function renderForm(){$('scenarioName').value=draft.name;$('annualBudget').value=draft.annualBudget;$('currency').value=draft.currency;$('budgetUnit').textContent=draft.currency;renderRows();updateSaveLabel()}
function renderRows(){$('categories').innerHTML=draft.categories.map((c,i)=>`<tr><td><div class="name-field"><i class="dot" style="background:${colors[i%colors.length]}"></i><input data-index="${i}" data-key="name" value="${escape(c.name)}" maxlength="60" aria-label="Nazwa kategorii ${i+1}" aria-describedby="c${i}name-error"></div><small id="c${i}name-error" class="error"></small></td><td data-label="Udział budżetu"><div class="number-field"><input data-index="${i}" data-key="allocationPercent" value="${escape(c.allocationPercent)}" inputmode="decimal" aria-label="Udział budżetu: ${escape(c.name)}" aria-describedby="c${i}allocationPercent-error"><span>%</span></div><small id="c${i}allocationPercent-error" class="error"></small></td><td data-label="Roczny ROI"><div class="number-field"><input data-index="${i}" data-key="expectedRoiPercent" value="${escape(c.expectedRoiPercent)}" inputmode="decimal" aria-label="Roczny ROI: ${escape(c.name)}" aria-describedby="c${i}expectedRoiPercent-error"><span>%</span></div><small id="c${i}expectedRoiPercent-error" class="error"></small></td><td data-label="Inwestycja"><span class="computed" id="investment${i}">—</span></td><td data-label="Oczekiwany zysk"><span class="computed" id="profit${i}">—</span></td><td data-label="Odzyskane środki"><span class="computed" id="recovered${i}">—</span></td><td><button class="delete" data-remove="${i}" aria-label="Usuń kategorię: ${escape(c.name)}">×</button></td></tr>`).join('');$('add').disabled=draft.categories.length>=30}
function updateSaveLabel(){let existing=scenarios.some(s=>s.id===draft.id);$('save').innerHTML=(existing?'Zapisz zmiany':'Zapisz scenariusz')+' <span>↗</span>';$('saveAs').hidden=!existing;$('count').textContent=scenarios.length}
function bars(items,currency,isPercent=false){const vals=items.map(x=>Number(x.value));if(!vals.some(v=>v!==0))return '<div class="empty">'+(isPercent?'Brak wartości ROI do przedstawienia':'Brak oczekiwanego zysku')+'</div>'+items.map(x=>`<div class="bar-caption"><span>${escape(x.name)}</span><strong>${escape(x.label)}</strong></div>`).join('');let low=Math.min(0,...vals),high=Math.max(0,...vals),range=high-low||1,zero=-low/range*100;return '<div class="bar-list" aria-label="Wykres słupkowy. Wartości i szczegóły podano tekstowo przy każdym słupku.">'+items.map((x,i)=>{let v=vals[i],left=v<0?(v-low)/range*100:zero,width=Math.abs(v)/range*100;return `<div class="bar-row" title="${escape(x.detail||x.label)}"><div class="bar-caption"><span>${escape(x.name)}</span><strong class="${v<0?'negative':'positive'}">${escape(x.label)}</strong></div><div class="bar-track" aria-hidden="true"><span class="bar-zero" style="left:${zero}%"></span><span class="bar-fill" style="left:${left}%;width:${width}%;background:${v<0?'#b76860':x.color||colors[i%colors.length]}"></span></div>${x.detail?`<small>${escape(x.detail)}</small>`:''}</div>`}).join('')+'</div>'}
function renderResults(){const r=calculate(draft),valid=Object.keys(r.errors).length===0,c=draft.currency;
 fieldError('annualBudget',r.errors.annualBudget);$('scenarioName').setAttribute('aria-invalid',validate(draft,true).errors.name?'true':'false');$('error-name').textContent=draft.name&&validate(draft,true).errors.name||'';
 draft.categories.forEach((cat,i)=>['name','allocationPercent','expectedRoiPercent'].forEach(k=>{let input=document.querySelector(`[data-index="${i}"][data-key="${k}"]`);input.setAttribute('aria-invalid',r.errors[`c${i}${k}`]?'true':'false');$(`c${i}${k}-error`).textContent=r.errors[`c${i}${k}`]||''}));
 $('allocationTotal').textContent=formatRatio(r.total||0n,100n)+'%';$('allocationError').textContent=r.errors.total||r.errors.categories||'';
 $('progress').innerHTML=r.rows.map((row,i)=>`<span style="width:${Number(row.p)/100}%;background:${colors[i%colors.length]}"></span>`).join('');$('results').hidden=!valid;$('resultError').hidden=valid;$('resultError').textContent='Uzupełnij poprawnie dane, aby zobaczyć wyniki i wykresy. '+Object.values(r.errors).join(' ');$('save').disabled=!!Object.keys(validate(draft,true).errors).length;$('saveAs').disabled=$('save').disabled;$('exportDraft').disabled=$('save').disabled;
 r.rows.forEach((row,i)=>{for(const key of ['investment','profit','recovered']){let el=$(key+i);el.textContent=valid?money(row[key],c):'—';el.className='computed '+(valid&&row[key]<0n?'negative':key==='profit'?'positive':'')}});
 $('reservePercent').textContent=valid?formatRatio(10000n-r.total,100n)+'%':'—';$('reserveAmount').textContent=valid?money(r.reserve,c):'—';if(!valid)return;
 const metric=(label,value,note,highlight=false)=>`<div class="metric ${highlight?'highlight':''}"><label>${label}</label><strong>${value}</strong><small>${note}</small></div>`;
 const amount=v=>`${formatRatio(v,10000000000n)} <span class="unit">${c}</span>`;
 $('metrics').innerHTML=metric('Zainwestowany budżet',amount(r.investment),formatRatio(r.total,100n)+'% całego budżetu')+metric('Niewydana rezerwa',amount(r.reserve),'Pozostaje w Twoim budżecie')+metric('Oczekiwany zysk',amount(r.profit),'Zysk ponad koszt inwestycji',true)+metric('ROI inwestycji',percent(r.roi),'Zwrot z zainwestowanych środków');
 $('extraMetrics').innerHTML=`<div class="muted">Odzyskane środki z inwestycji<strong>${money(r.recovered,c)}</strong></div><div class="muted">Zysk względem całego budżetu<strong>${percent(r.budgetRoi)}</strong></div><div class="muted">Środki końcowe z rezerwą<strong>${money(r.final,c)}</strong></div>`;
 if(r.budget===0n)$('donut').innerHTML='<div class="empty">Podaj budżet większy od zera, aby zobaczyć jego podział.</div>';else{const segments=r.rows.map((x,i)=>({name:x.name,p:x.p,value:x.investment,color:colors[i%colors.length]})).filter(x=>x.p>0n);if(r.total<10000n)segments.push({name:'Rezerwa',p:10000n-r.total,value:r.reserve,color:'#c5ccc2'});let start=0;const gradient=segments.map(s=>{let end=start+Number(s.p)/100;let stop=`${s.color} ${start}% ${end}%`;start=end;return stop}).join(',');$('donut').innerHTML=`<div class="donut-layout"><div class="donut" role="img" aria-label="Podział budżetu, szczegółowe wartości w legendzie" style="background:conic-gradient(${gradient})"><div class="donut-center"><small>CAŁY BUDŻET</small><strong>${formatRatio(r.budget,10000000000n,0)}</strong><small>${c}</small></div></div><div class="legend">${segments.map(s=>`<div class="legend-row"><i class="dot" style="background:${s.color}"></i><span class="legend-name">${escape(s.name)}</span><strong>${formatRatio(s.p,100n)}%</strong><small>${money(s.value,c)}</small></div>`).join('')}</div></div>`;}
 $('profitChart').innerHTML=bars(r.rows.filter(x=>x.p>0n).map((x,i)=>({name:x.name,value:x.profit,label:money(x.profit,c),detail:`Inwestycja: ${money(x.investment,c)} · ROI: ${formatRatio(x.r,100n)}%`,color:colors[draft.categories.findIndex(cat=>cat.id===x.id)%colors.length]})),c);
}
function writeScenarios(next){if(externalPending){notify('Dane zmieniły się w innej karcie. Najpierw odśwież i zdecyduj o aktywnym szkicu.');return false}if(corrupt){notify('Najpierw pobierz kopię i zresetuj uszkodzony zapis.');return false}try{localStorage.setItem(KEY,JSON.stringify({schemaVersion:1,scenarios:next}));scenarios=next;return true}catch{localError('Nie udało się zapisać scenariuszy. Brak dostępu lub miejsca.');return false}}
async function firstSaveNotice(){try{if(localStorage.getItem(INFO))return true}catch{}let choice=await modal('Scenariusze zostają w tej przeglądarce','Dane są dostępne tylko w tym profilu przeglądarki i pod tym adresem. Wyczyszczenie danych witryny je usuwa. Regularnie eksportuj kopię JSON.',[['Anuluj','cancel'],['Rozumiem, zapisz','yes',true]]);if(choice!=='yes')return false;try{localStorage.setItem(INFO,'1')}catch{}return true}
async function saveScenario(asNew){let s;try{s=snapshot(draft,asNew)}catch(e){notify(e.message);return false}if(!await firstSaveNotice())return false;const index=scenarios.findIndex(x=>x.id===s.id),next=clone(scenarios);if(index<0)next.push(s);else next[index]=s;if(!writeScenarios(next))return false;draft=s;baseline=JSON.stringify(draft);persistDraft();renderForm();renderResults();notify('Scenariusz zapisany lokalnie.');return true}
function showTab(t){tab=t;['calculator','scenarios','compare'].forEach(id=>$(id).hidden=id!==t);document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));$('crumb').textContent={calculator:'Kalkulator',scenarios:'Moje scenariusze',compare:'Porównanie'}[t];$('heading').textContent={calculator:'Dobry plan zaczyna się od liczb.',scenarios:'Twoje plany. Wszystko w jednym miejscu.',compare:'Porównaj możliwości. Wybierz świadomie.'}[t];$('subtitle').textContent={calculator:'Podziel budżet i zobacz, jaki efekt mogą przynieść Twoje działania.',scenarios:'Wracaj do zapisanych wariantów i buduj kolejne na ich podstawie.',compare:'Sprawdź różnice w zysku, ROI i alokacji — obok wybranego wariantu bazowego.'}[t];if(t==='scenarios')renderScenarios();if(t==='compare')renderCompare();location.hash={calculator:'kalkulator',scenarios:'scenariusze',compare:'porownanie'}[t]}
function sorted(){return [...scenarios].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))}
function selectedToggle(id,checked){if(checked){if(selected.size>=4){notify('Możesz porównać maksymalnie 4 scenariusze.');return false}selected.add(id)}else selected.delete(id);return true}
function renderScenarios(){updateSaveLabel();$('scenarios').innerHTML=`<div class="scenario-toolbar"><span class="muted">${scenarios.length} zapisanych scenariuszy · od ostatnio zmienionego</span><div class="actions"><button class="button" data-action="import">Importuj JSON</button><button class="button" data-action="exportAll" ${!scenarios.length?'disabled':''}>Eksportuj wszystkie</button><button class="button primary" data-action="compare">Porównaj (${selected.size}/4) ⇄</button></div></div>${!scenarios.length?'<div class="panel empty"><h2>Tu znajdziesz swoje zapisane plany.</h2><p>Stwórz pierwszy scenariusz w kalkulatorze albo zaimportuj kopię JSON.</p><button class="button primary" data-action="calculator">Przejdź do kalkulatora ↗</button></div>':'<div class="scenario-grid">'+sorted().map(s=>{let r=calculate(s);return `<article class="panel scenario-card"><h2>${escape(s.name)}</h2><span class="muted">Aktualizacja: ${new Intl.DateTimeFormat('pl-PL',{dateStyle:'medium',timeStyle:'short',timeZone:'Europe/Warsaw'}).format(new Date(s.updatedAt))}</span><div class="scenario-stats"><div class="muted">Budżet roczny<strong>${money(r.budget,s.currency)}</strong></div><div class="muted">Oczekiwany zysk<strong class="${r.profit<0n?'negative':'positive'}">${money(r.profit,s.currency)}</strong></div><div class="muted">ROI inwestycji<strong>${percent(r.roi)}</strong></div><div class="muted">Rezerwa<strong>${money(r.reserve,s.currency)}</strong></div></div><div class="actions"><button class="button primary" data-load="${escape(s.id)}">Wczytaj</button><button class="button" data-duplicate="${escape(s.id)}">Duplikuj</button><button class="button" data-export="${escape(s.id)}">Eksportuj</button><button class="button" data-delete="${escape(s.id)}">Usuń</button></div><label class="check-label"><input type="checkbox" data-select="${escape(s.id)}" ${selected.has(s.id)?'checked':''}>Wybierz do porównania</label></article>`}).join('')+'</div>'}`;}
function renderCompare(){const chosen=scenarios.filter(s=>selected.has(s.id));$('compare').innerHTML=`<div class="panel comparison-select">${sorted().map(s=>`<label class="check-label"><input type="checkbox" data-select="${escape(s.id)}" ${selected.has(s.id)?'checked':''}> ${escape(s.name)} <span class="muted">${s.currency}</span></label>`).join('')||'<span class="muted">Zapisz co najmniej dwa scenariusze w kalkulatorze.</span>'}</div><div id="comparisonContent"></div>`;let el=$('comparisonContent');if(chosen.length<2){el.innerHTML='<div class="panel empty"><h2>Jak wygląda Twój plan B?</h2><p>Wybierz 2–4 zapisane scenariusze, aby porównać ich wyniki.</p><button class="button" data-action="scenarios">Moje scenariusze</button></div>';return}if(new Set(chosen.map(s=>s.currency)).size!==1){el.innerHTML='<div class="notice" role="alert">Scenariusze mają różne waluty. Wybierz warianty w jednej walucie — aplikacja nie przelicza kursów.</div>';return}if(!chosen.some(s=>s.id===baseId))baseId=chosen[0].id;let results=chosen.map(calculate),bi=chosen.findIndex(s=>s.id===baseId),br=results[bi],c=chosen[0].currency;
 let bestProfit=results.reduce((max,r)=>r.profit>max?r.profit:max,results[0].profit),available=results.filter(r=>r.roi!==null),bestRoi=available.length?available.reduce((max,r)=>r.roi.n*max.d>max.n*r.roi.d?r.roi:max,available[0].roi):null;
 const rows=[['Roczny budżet','budget'],['Zainwestowany budżet','investment'],['Niewydana rezerwa','reserve'],['Oczekiwany zysk','profit'],['ROI inwestycji','roi'],['Zysk względem budżetu','budgetRoi'],['Środki końcowe z rezerwą','final']];
 el.innerHTML=`<div class="comparison-base"><label for="baseSelect">Wariant bazowy</label><select id="baseSelect">${chosen.map(s=>`<option value="${escape(s.id)}" ${s.id===baseId?'selected':''}>${escape(s.name)}</option>`).join('')}</select></div>${new Set(chosen.map(s=>s.annualBudget)).size>1?'<div class="notice">Budżety scenariuszy różnią się. Najwyższy zysk i najwyższy ROI to dwa oddzielne kryteria; porównuj także wielkość inwestycji.</div>':''}<div class="panel table-scroll"><table class="comparison-table"><thead><tr><th>Metryka</th>${chosen.map(s=>`<th>${escape(s.name)}${s.id===baseId?'<br><span class="badge">WARIANT BAZOWY</span>':''}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,key])=>`<tr><th scope="row">${label}</th>${results.map((r,i)=>{let value=['roi','budgetRoi'].includes(key)?percent(r[key]):money(r[key],c),extra='';if(key==='profit'){let d=r.profit-br.profit;extra=`<small>${d>0n?'+':''}${money(d,c)} względem bazy</small>`;if(r.profit===bestProfit)extra+='<span class="badge">Najwyższy zysk</span>'}if(key==='roi'){if(r.roi&&br.roi){let n=r.roi.n*br.roi.d-br.roi.n*r.roi.d;extra=`<small>${n>0n?'+':''}${formatRatio(n,r.roi.d*br.roi.d)} p.p. względem bazy</small>`}else extra='<small>Różnica ROI: nie dotyczy</small>';if(r.roi&&bestRoi&&r.roi.n*bestRoi.d===bestRoi.n*r.roi.d)extra+='<span class="badge">Najwyższy ROI</span>'}return `<td>${value}${extra}</td>`}).join('')}</tr>`).join('')}</tbody></table></div><div class="charts-grid"><section class="panel chart-panel"><h2>Oczekiwany zysk · ${c}</h2>${bars(results.map((r,i)=>({name:chosen[i].name,value:r.profit,label:money(r.profit,c)})),c)}</section><section class="panel chart-panel"><h2>ROI zainwestowanych środków · %</h2>${bars(results.filter(r=>r.roi!==null).map(r=>{let i=results.indexOf(r);return {name:chosen[i].name,value:Number(r.roi.n)/Number(r.roi.d),label:percent(r.roi)}}),c,true)}${results.some(r=>!r.roi)?'<p class="muted">Warianty bez inwestycji: ROI nie dotyczy; pominięte w rankingu.</p>':''}</section></div><details class="panel category-comparison"><summary>Porównanie alokacji według kategorii</summary><div class="table-scroll"><table class="comparison-table"><thead><tr><th>Kategoria</th>${chosen.map(s=>`<th>${escape(s.name)}</th>`).join('')}</tr></thead><tbody>${[...new Map(chosen.flatMap(s=>s.categories).map(cat=>[normalize(cat.name),cat.name])).entries()].map(([key,name],index)=>`<tr><th scope="row"><i class="dot" style="display:inline-block;margin-right:7px;background:${colors[index%colors.length]}"></i>${escape(name)}</th>${results.map(r=>{let cat=r.rows.find(cat=>normalize(cat.name)===key);return `<td>${cat?formatRatio(cat.p,100n):'0,00'}%<small>${cat?money(cat.investment,c):money(0n,c)}</small><small>ROI: ${cat?formatRatio(cat.r,100n)+'%':'Nie dotyczy'}</small></td>`}).join('')}</tr>`).join('')}</tbody></table></div></details><p class="comparison-note">Kategorie dopasowujemy według nazw, pomijając wielkość liter i nadmiarowe spacje. Brak kategorii oznacza zerową alokację.</p>`;
 $('baseSelect').onchange=e=>{baseId=e.target.value;renderCompare()};}
$('categories').addEventListener('input',e=>{let {index,key}=e.target.dataset;if(index===undefined)return;draft.categories[Number(index)][key]=e.target.value;persistDraft();renderResults()});
$('categories').addEventListener('click',async e=>{let b=e.target.closest('[data-remove]');if(!b)return;let i=Number(b.dataset.remove),cat=draft.categories[i];let p=Number(cat.allocationPercent.replace(',','.').replace(/\s/g,''));if((p>0||!Number.isFinite(p))&&await modal('Usunąć kategorię?',`Kanał „${cat.name}” zostanie usunięty, a jego udział przejdzie do rezerwy.`,[['Anuluj','cancel'],['Usuń','yes',true]])!=='yes')return;draft.categories.splice(i,1);renderRows();renderResults();persistDraft()});
$('scenarioName').oninput=e=>{draft.name=e.target.value;persistDraft();renderResults()};$('annualBudget').oninput=e=>{draft.annualBudget=e.target.value;persistDraft();renderResults()};$('currency').onchange=e=>{draft.currency=e.target.value;$('budgetUnit').textContent=draft.currency;persistDraft();renderResults()};
$('add').onclick=()=>{if(draft.categories.length>=30)return;let n=1;while(draft.categories.some(c=>normalize(c.name)===normalize('Nowa kategoria '+n)))n++;draft.categories.push({id:uid(),name:'Nowa kategoria '+n,allocationPercent:'0',expectedRoiPercent:'0'});renderRows();renderResults();persistDraft();document.querySelector(`[data-index="${draft.categories.length-1}"][data-key="name"]`).focus()};
$('new').onclick=()=>guard(()=>setDraft(fresh()));$('example').onclick=()=>guard(()=>{let s=fresh();s.name='Przykład · plan z rezerwą';s.annualBudget='100000';s.categories[0].allocationPercent='40';s.categories[0].expectedRoiPercent='50';s.categories[1].allocationPercent='30';s.categories[1].expectedRoiPercent='100';s.categories[3].allocationPercent='20';s.categories[3].expectedRoiPercent='-25';setDraft(s);baseline=JSON.stringify(fresh());persistDraft();notify('Wczytano przykładowe założenia ROI.');});
$('save').onclick=()=>saveScenario(false);$('saveAs').onclick=()=>saveScenario(true);$('exportDraft').onclick=()=>{try{backup([snapshot(draft)])}catch(e){notify(e.message)}};
$('help').onclick=()=>modal('ROI oznacza zysk ponad koszt','Przy inwestycji 1 000 PLN i ROI 50% zysk wynosi 500 PLN, a odzyskane środki 1 500 PLN.\n\nROI całego planu to zysk ÷ zainwestowane środki, nie średnia ROI kanałów. Rezerwa nie generuje zysku i nie wchodzi do podstawy ROI.\n\nWyniki są roczną symulacją. ROI jest Twoim założeniem, a marginalny zwrot z każdej złotówki pozostaje stały.',[['Rozumiem','ok',true]]);
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>showTab(b.dataset.tab));
$('main').addEventListener('change',e=>{if(e.target.dataset.select){if(!selectedToggle(e.target.dataset.select,e.target.checked))e.target.checked=false;else tab==='compare'?renderCompare():renderScenarios()}});
$('main').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset.action;if(a){if(['calculator','scenarios','compare'].includes(a))showTab(a);if(a==='import')$('importFile').click();if(a==='exportAll')backup(scenarios)}const id=b.dataset.load||b.dataset.duplicate||b.dataset.delete||b.dataset.export;if(!id)return;const s=scenarios.find(s=>s.id===id);if(!s)return;if(b.dataset.load)guard(()=>setDraft(s));if(b.dataset.export)backup([s]);if(b.dataset.duplicate)guard(()=>{let copy=snapshot(s,true);copy.name=(s.name.slice(0,70)+' · kopia');if(writeScenarios([...scenarios,copy])){setDraft(copy);notify('Zapisano duplikat z nowym ID.')}});if(b.dataset.delete&&await modal('Usunąć scenariusz?',`Usuniesz „${s.name}” z zapisanych scenariuszy. Eksportuj go, jeśli potrzebujesz kopii.`,[['Anuluj','cancel'],['Usuń','yes',true]])==='yes'){if(writeScenarios(scenarios.filter(x=>x.id!==id))){selected.delete(id);updateSaveLabel();if(tab==='scenarios')renderScenarios();if(tab==='compare')renderCompare();notify('Scenariusz usunięty.')}}});
$('importFile').onchange=async e=>{let file=e.target.files[0];if(!file)return;try{if(file.size>1048576)throw Error('Plik przekracza 1 MB.');let incoming=readBackup(await file.text());if(incoming.length&&!await firstSaveNotice())return;if(writeScenarios([...scenarios,...incoming])){renderScenarios();notify(`Zaimportowano ${incoming.length} scenariuszy. Istniejące warianty zachowano.`)}}catch(err){notify('Import odrzucony: '+err.message)}finally{e.target.value=''}};
window.addEventListener('storage',e=>{if([KEY,DRAFT].includes(e.key)||e.key===null){clearTimeout(timer);$('external').hidden=false;storageBlocked=true;externalPending=true}});
$('reload').onclick=()=>guard(()=>location.reload());window.addEventListener('beforeunload',e=>{if(storageBlocked&&dirty()){e.preventDefault();e.returnValue=''}});
renderForm();renderResults();showTab(location.hash==='#scenariusze'?'scenarios':location.hash==='#porownanie'?'compare':'calculator');
